/**
 * The one API client the app uses. Typed from the API's OpenAPI schema (schema.d.ts,
 * generated by `npm run api:types`), so a wrong path or field is a compile error.
 * .NET: like an NSwag/Refit client generated from swagger.json, registered once.
 */
import createClient from 'openapi-fetch';

import { createAuth } from './auth';
import type { paths } from './schema';
import { secureTokenStore } from './tokens';

/** Set in mobile/.env (see .env.example). Inlined into the bundle when it's built. */
export const API_URL = (process.env.EXPO_PUBLIC_API_URL ?? '').replace(/\/+$/, '');

export const auth = createAuth({
  baseUrl: API_URL,
  store: secureTokenStore,
  fetch: (request) => fetch(request),
  now: () => Date.now(),
});

export const api = createClient<paths>({ baseUrl: API_URL, fetch: auth.authedFetch });
